import{_ as a,o as n,c as t,a3 as p}from"./chunks/framework.Cc-oPviL.js";const d=JSON.parse('{"title":"01 · 分层模型与一次请求的一生","description":"","frontmatter":{},"headers":[],"relativePath":"bagu/network/01.md","filePath":"bagu/network/01.md"}'),e={name:"bagu/network/01.md"};function o(l,s,i,r,c,g){return n(),t("div",null,[...s[0]||(s[0]=[p(`<h1 id="_01-·-分层模型与一次请求的一生" tabindex="-1">01 · 分层模型与一次请求的一生 <a class="header-anchor" href="#_01-·-分层模型与一次请求的一生" aria-label="Permalink to &quot;01 · 分层模型与一次请求的一生&quot;">​</a></h1><blockquote><p>这是网络模块的总纲。<strong>先看懂这篇的&quot;封装-解封装&quot;过程，后面四篇才有地方挂。</strong></p></blockquote><h2 id="一句话本质" tabindex="-1">一句话本质 <a class="header-anchor" href="#一句话本质" aria-label="Permalink to &quot;一句话本质&quot;">​</a></h2><p>数据从上往下走，每层<strong>加一个头</strong>（封装）；到了对方从下往上走，每层<strong>拆一个头</strong>（解封装）。网络的一切复杂度，都在这些头里。</p><h2 id="生活类比-寄快递的层层包装" tabindex="-1">生活类比：寄快递的层层包装 <a class="header-anchor" href="#生活类比-寄快递的层层包装" aria-label="Permalink to &quot;生活类比：寄快递的层层包装&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>你写的信（应用层数据）</span></span>
<span class="line"><span>  v 装进信封，写上&quot;收件人、寄件人&quot;（加 TCP 头）</span></span>
<span class="line"><span>  v 装进快递袋，写上&quot;地址、单号&quot;（加 IP 头）</span></span>
<span class="line"><span>  v 贴上面单，写上&quot;本小区 3 号楼&quot;（加 MAC 头）</span></span>
<span class="line"><span>  v 交给快递员（物理传输）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>到了分拣中心：</span></span>
<span class="line"><span>  v 撕掉面单（拆 MAC 头）—— 因为要重新决定下一站</span></span>
<span class="line"><span>  v 看快递袋上的地址（IP 头）—— 决定往哪发</span></span>
<span class="line"><span>  v 贴上新面单（加新 MAC 头）—— 下一跳</span></span>
<span class="line"><span></span></span>
<span class="line"><span>到了收件人：</span></span>
<span class="line"><span>  v 撕面单（拆 MAC）</span></span>
<span class="line"><span>  v 撕快递袋（拆 IP）</span></span>
<span class="line"><span>  v 拆信封（拆 TCP）</span></span>
<span class="line"><span>  v 拿到信（应用层数据）</span></span></code></pre></div><p><strong>关键</strong>：分拣中心（路由器）只拆到&quot;快递袋&quot;（IP 层），<strong>不会拆信封</strong>（TCP 层）。这是分层的精髓——<strong>每一层只关心自己那层的头</strong>。</p><h2 id="核心机制" tabindex="-1">核心机制 <a class="header-anchor" href="#核心机制" aria-label="Permalink to &quot;核心机制&quot;">​</a></h2><h3 id="一、封装-从上往下-逐层加头" tabindex="-1">一、封装：从上往下，逐层加头 <a class="header-anchor" href="#一、封装-从上往下-逐层加头" aria-label="Permalink to &quot;一、封装：从上往下，逐层加头&quot;">​</a></h3><p>假设浏览器要发一个 HTTP 请求 <code>GET /a</code>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>应用层   GET /a HTTP/1.1  +  Host: x.com</span></span>
<span class="line"><span>           |</span></span>
<span class="line"><span>           |  加 TCP 头：源端口、目的端口、序号、窗口</span></span>
<span class="line"><span>           v</span></span>
<span class="line"><span>传输层   [TCP头][GET /a ...]</span></span>
<span class="line"><span>           |</span></span>
<span class="line"><span>           |  加 IP 头：源 IP、目的 IP、TTL</span></span>
<span class="line"><span>           v</span></span>
<span class="line"><span>网络层   [IP头][TCP头][GET /a ...]</span></span>
<span class="line"><span>           |</span></span>
<span class="line"><span>           |  加 MAC 头：源 MAC、目的 MAC、校验</span></span>
<span class="line"><span>           v</span></span>
<span class="line"><span>链路层   [MAC头][IP头][TCP头][GET /a ...][FCS]</span></span></code></pre></div><p><strong>每个头解决的问题</strong>：</p><table tabindex="0"><thead><tr><th>层</th><th>头里有什么</th><th>解决什么</th></tr></thead><tbody><tr><td>链路层</td><td>源 MAC、目的 MAC</td><td>这一跳交给谁</td></tr><tr><td>网络层</td><td>源 IP、目的 IP、TTL</td><td>最终送到哪、能活多久（防环）</td></tr><tr><td>传输层</td><td>源端口、目的端口、序号、确认号、窗口</td><td>交给哪个进程、保证不丢不乱</td></tr></tbody></table><h3 id="二、mtu-与-mss-为什么要切" tabindex="-1">二、MTU 与 MSS：为什么要切 <a class="header-anchor" href="#二、mtu-与-mss-为什么要切" aria-label="Permalink to &quot;二、MTU 与 MSS：为什么要切&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>MTU（Maximum Transmission Unit）= 链路层能承载的最大帧载荷，以太网默认 1500 字节</span></span>
<span class="line"><span>MSS（Maximum Segment Size）= TCP 段的最大数据长度 = MTU - IP头(20) - TCP头(20) = 1460</span></span></code></pre></div><p><strong>为什么要切</strong>：链路层一次传不了那么大的数据。你发 1MB 的数据，TCP 会切成约 700 个 MSS 大小的段。</p><p><strong>切太大会怎样</strong>：如果 IP 包超过 MTU 且不允许分片，会被丢弃，返回 ICMP &quot;需要分片&quot;。这就是 <strong>PMTUD（路径 MTU 发现）</strong> 要解决的问题，也是某些网络&quot;能 ping 通但打不开网页&quot;的原因。</p><h3 id="三、转发-每一跳发生了什么" tabindex="-1">三、转发：每一跳发生了什么 <a class="header-anchor" href="#三、转发-每一跳发生了什么" aria-label="Permalink to &quot;三、转发：每一跳发生了什么&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>主机 A --&gt; 路由器 1 --&gt; 路由器 2 --&gt; 主机 B</span></span></code></pre></div><p>在<strong>主机 A</strong>：</p><ol><li>查路由表：目的 IP 不在本网段 &gt; 交给默认网关（路由器 1）。</li><li>查 ARP：网关 IP 对应的 MAC 是多少。</li><li>封装：目的 MAC = 路由器 1 的 MAC，目的 IP = 主机 B 的 IP。</li></ol><p>在<strong>路由器 1</strong>：</p><ol><li>拆链路层头（看目的 MAC 是自己，收下）。</li><li>看 IP 头里的目的 IP，<strong>TTL 减 1</strong>，查路由表决定下一跳。</li><li><strong>重新封装</strong>：目的 MAC = 路由器 2 的 MAC，<strong>源 MAC = 路由器 1 出接口的 MAC</strong>，<strong>IP 头不变</strong>。</li></ol><p><strong>必记结论</strong>：</p><ul><li><strong>MAC 每跳都变，IP 端到端不变</strong>（NAT 场景例外）。</li><li><strong>TTL 每跳减 1</strong>，减到 0 就丢弃并回 ICMP 超时——这是 <code>traceroute</code> 的原理。</li></ul><h3 id="四、分片与重组" tabindex="-1">四、分片与重组 <a class="header-anchor" href="#四、分片与重组" aria-label="Permalink to &quot;四、分片与重组&quot;">​</a></h3><p>IP 层如果遇到超过 MTU 的包，可以分片（IPv4）。但<strong>分片很糟</strong>：</p><ul><li>任一分片丢失，整个包要重传。</li><li>分片增加路由器负担。</li></ul><p>所以现代做法是：<strong>IP 层不分片（设 DF 位），由 TCP 按 MSS 切好</strong>。IPv6 干脆取消了路由器分片。</p><h3 id="五、端口-数据交给哪个进程" tabindex="-1">五、端口：数据交给哪个进程 <a class="header-anchor" href="#五、端口-数据交给哪个进程" aria-label="Permalink to &quot;五、端口：数据交给哪个进程&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>一个 TCP 连接由四元组唯一标识：</span></span>
<span class="line"><span>  (源IP, 源端口, 目的IP, 目的端口)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>所以：</span></span>
<span class="line"><span>  同一个客户端可以同时开很多连接访问同一个服务器 —— 源端口不同</span></span>
<span class="line"><span>  一个服务器端口（比如 80）可以同时服务成千上万个连接 —— 靠四元组区分</span></span></code></pre></div><p><strong>这解释了一个常见疑问</strong>：为什么服务端只监听一个 80 端口，却能处理上万并发？因为<strong>连接不是靠端口区分的，是靠四元组区分的</strong>。</p><h3 id="六、完整时序" tabindex="-1">六、完整时序 <a class="header-anchor" href="#六、完整时序" aria-label="Permalink to &quot;六、完整时序&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>① 浏览器 -&gt; 本地 DNS   查询 www.example.com              【网络 05】</span></span>
<span class="line"><span>② 本地 DNS -&gt; 浏览器   返回 IP 93.184.216.34</span></span>
<span class="line"><span>③ 浏览器 -&gt; 服务器     SYN                                【网络 02】</span></span>
<span class="line"><span>④ 服务器 -&gt; 浏览器     SYN+ACK</span></span>
<span class="line"><span>⑤ 浏览器 -&gt; 服务器     ACK          =&gt; TCP 连接建立</span></span>
<span class="line"><span>⑥ 浏览器 -&gt; 服务器     TLS 握手（若 HTTPS）               【网络 04】</span></span>
<span class="line"><span>⑦ 浏览器 -&gt; 服务器     GET /index.html                    【网络 04】</span></span>
<span class="line"><span>⑧ 服务器 -&gt; 浏览器     200 OK + HTML</span></span>
<span class="line"><span>⑨ 双向               数据分片、编号、滑动窗口            【网络 03】</span></span>
<span class="line"><span>⑩ 浏览器 -&gt; 服务器     FIN                                【网络 02】</span></span>
<span class="line"><span>⑪ 服务器 -&gt; 浏览器     ACK</span></span>
<span class="line"><span>⑫ 服务器 -&gt; 浏览器     FIN</span></span>
<span class="line"><span>⑬ 浏览器 -&gt; 服务器     ACK          =&gt; 连接关闭</span></span></code></pre></div><h2 id="为什么这么设计" tabindex="-1">为什么这么设计 <a class="header-anchor" href="#为什么这么设计" aria-label="Permalink to &quot;为什么这么设计&quot;">​</a></h2><h3 id="反事实-1-如果不分层-会怎样" tabindex="-1">反事实 1：如果不分层，会怎样 <a class="header-anchor" href="#反事实-1-如果不分层-会怎样" aria-label="Permalink to &quot;反事实 1：如果不分层，会怎样&quot;">​</a></h3><p>一个协议要同时管&quot;找路 + 不丢包 + 数据格式 + 加密&quot;。后果：</p><ul><li>换 WiFi 就要重写整个协议栈。</li><li>想给 HTTP 加密（HTTPS），得改底层寻址逻辑。</li><li>每个应用（邮件、网页、视频）都要自己实现可靠传输。</li></ul><p>分层让<strong>每一层可以独立演进</strong>：HTTP/2 只改了应用层，TCP 一点没动；QUIC 把可靠传输搬到 UDP 上，只动了传输层。</p><h3 id="反事实-2-如果路由器要拆到应用层-会怎样" tabindex="-1">反事实 2：如果路由器要拆到应用层，会怎样 <a class="header-anchor" href="#反事实-2-如果路由器要拆到应用层-会怎样" aria-label="Permalink to &quot;反事实 2：如果路由器要拆到应用层，会怎样&quot;">​</a></h3><p>路由器要理解 HTTP、SMTP、FTP 每种协议的格式——不可能，而且每出一个新协议就要升级所有路由器。</p><p>所以路由器只拆到 IP 层：<strong>它只需要知道&quot;目的 IP 是谁&quot;，不需要知道&quot;里面装的是什么&quot;</strong>。这就是&quot;端到端原则&quot;：<strong>复杂的功能放在端上，网络中间尽量简单</strong>。</p><h3 id="反事实-3-如果没有端口-会怎样" tabindex="-1">反事实 3：如果没有端口，会怎样 <a class="header-anchor" href="#反事实-3-如果没有端口-会怎样" aria-label="Permalink to &quot;反事实 3：如果没有端口，会怎样&quot;">​</a></h3><p>一台机器上跑着浏览器、微信、数据库。数据到了，交给谁？</p><p>没有端口的话，只能靠&quot;应用自己识别数据&quot;——每个应用都要读所有收到的包，判断&quot;这是不是我的&quot;。既低效又不安全。</p><p>端口本质是<strong>给进程编了个号，让内核能直接分发</strong>。</p><h2 id="面试怎么问" tabindex="-1">面试怎么问 <a class="header-anchor" href="#面试怎么问" aria-label="Permalink to &quot;面试怎么问&quot;">​</a></h2><p><strong>Q：TCP/IP 四层（或 OSI 七层）分别是什么？各层有什么协议？</strong></p><blockquote><p>四层：应用层（HTTP/DNS/FTP）、传输层（TCP/UDP）、网络层（IP/ICMP/ARP 争议）、链路层（以太网/ARP）。 七层：物理、数据链路、网络、传输、会话、表示、应用。<strong>说完补一句&quot;OSI 是教学模型，实际是 TCP/IP 四层&quot;</strong>，显得不背书。</p></blockquote><p><strong>Q：数据从应用层到物理层，经过了什么？</strong></p><blockquote><p>逐层封装，每层加头：TCP 头（端口、序号）&gt; IP 头（IP、TTL）&gt; MAC 头（MAC、FCS）。到对方逐层解封装，每层拆自己那个头，把剩下的往上交。</p></blockquote><p><strong>Q：路由器转发时，什么变了什么没变？</strong></p><blockquote><p><strong>变了</strong>：源 MAC、目的 MAC（每跳重写）、TTL（每跳减 1）。 <strong>没变</strong>：源 IP、目的 IP（NAT 场景除外）、TCP 头（端口、序号全部不变）。 这是区分&quot;懂不懂分层&quot;的经典题。</p></blockquote><p><strong>Q：为什么服务端一个端口能处理上万连接？</strong></p><blockquote><p>因为连接由<strong>四元组</strong>标识（源IP、源端口、目的IP、目的端口），不是由端口标识。不同客户端的源 IP/端口不同，就是不同的连接。</p></blockquote><p><strong>追问链</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>一次请求经过哪些层？</span></span>
<span class="line"><span>  &gt; 每层加了什么头？（端口 / IP / MAC）</span></span>
<span class="line"><span>    &gt; 路由器拆到哪一层？（只到 IP 层）</span></span>
<span class="line"><span>      &gt; 为什么不多拆？（端到端原则，中间要简单）</span></span>
<span class="line"><span>        &gt; MAC 每跳都变，IP 不变，为什么？（MAC 只管这一跳）</span></span>
<span class="line"><span>          &gt; 那 NAT 呢？（NAT 会改 IP，所以破坏了端到端，是过渡方案）</span></span></code></pre></div><h2 id="和其他知识的连接" tabindex="-1">和其他知识的连接 <a class="header-anchor" href="#和其他知识的连接" aria-label="Permalink to &quot;和其他知识的连接&quot;">​</a></h2><ul><li><strong>&lt; 来自</strong> <a href="/study-hub/bagu/network/00">网络导读：两台机器怎么说话</a>：这是模块总纲的展开</li><li><strong>&lt; 来自</strong> <a href="/study-hub/bagu/os/05">内核态与系统调用：用户程序怎么&quot;申请&quot;做事</a>：封装解封装在内核协议栈里完成，<code>send</code>/<code>recv</code> 是入口</li><li><strong>&gt; 影响</strong> <a href="/study-hub/bagu/network/02">TCP 连接管理：三次握手、四次挥手、TIME_WAIT</a>：TCP 头里的端口和序号，是后面所有机制的基础</li><li><strong>&gt; 影响</strong> <a href="/study-hub/bagu/network/03">TCP 可靠传输与拥塞控制</a>：MSS 决定了切段大小，直接影响滑动窗口的效率</li><li><strong>&gt; 影响</strong> <a href="/study-hub/bagu/network/04">HTTP / HTTPS 与缓存</a>：HTTP 是应用层数据，它不知道下面怎么传的</li><li><strong>&gt; 影响</strong> <a href="/study-hub/bagu/network/05">DNS 与 ARP：两个&quot;翻译官&quot;</a>：DNS 是应用层协议（自己也要走 UDP/TCP），ARP 是链路层的&quot;翻译官&quot;</li></ul><h2 id="自测-3-问" tabindex="-1">自测 3 问 <a class="header-anchor" href="#自测-3-问" aria-label="Permalink to &quot;自测 3 问&quot;">​</a></h2><p><strong>Q1：路由器转发时，为什么要重写 MAC 头？</strong></p><details class="details custom-block"><summary>点开看答案</summary><p>因为 <strong>MAC 地址只在同一个局域网（广播域）内有效</strong>。</p><p>主机 A 和主机 B 可能隔了 10 个路由器，A 根本不知道 B 的 MAC（也不需要知道）。A 只知道&quot;下一跳是网关&quot;，所以把目的 MAC 写成网关的。</p><p>网关收到后，要发给下一个网关，就得把目的 MAC 改成下一个网关的 MAC。<strong>每一跳都是&quot;当前节点 &gt; 下一个节点&quot;的关系，所以 MAC 每跳都要重写</strong>。</p><p>而 IP 是端到端的最终地址，全程不变（NAT 除外）。</p></details><p><strong>Q2：为什么服务端 80 端口能同时处理上万连接？</strong></p><details class="details custom-block"><summary>点开看答案</summary><p>因为<strong>端口不是连接的唯一标识</strong>，四元组才是：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>(客户端IP, 客户端端口, 服务器IP, 服务器端口)</span></span></code></pre></div><p>一万个客户端连过来，服务器 IP 和端口都是 <code>1.2.3.4:80</code>，但客户端 IP/端口各不相同，所以是 1 万个不同的连接。</p><p>内核的 socket 表按四元组查找，每个连接一个 socket 结构。<strong>&quot;监听 80 端口&quot;的那个 socket 只负责接受新连接（accept），接受后创建的新 socket 才承载数据</strong>。</p></details><p><strong>Q3：TTL 是干什么的？为什么需要它？</strong></p><details class="details custom-block"><summary>点开看答案</summary><p>TTL（Time To Live）是 IP 头里的一个计数器，<strong>每经过一个路由器减 1，减到 0 就丢弃并回一个 ICMP 超时</strong>。</p><p>存在理由：<strong>防止路由环路把网络打爆</strong>。如果路由表配错形成环，包会在两个路由器之间无限打转，每秒几百万个包会把链路彻底堵死。有了 TTL，最多转 64 跳就死掉。</p><p>副产品：<code>traceroute</code> 就是利用它——发 TTL=1 的包，第一个路由器回超时，就知道第一跳是谁；TTL=2 就知道第二跳，依次推出整条路径。</p></details><h2 id="类比失效处-易错点" tabindex="-1">类比失效处 / 易错点 <a class="header-anchor" href="#类比失效处-易错点" aria-label="Permalink to &quot;类比失效处 / 易错点&quot;">​</a></h2><ul><li><strong>&quot;快递袋&quot;类比会让人以为分拣中心要拆开看</strong>。实际路由器<strong>只看 IP 头</strong>，连 TCP 头都不看（除了 NAT 和防火墙）。</li><li><strong>&quot;每层加头&quot;不是无限的</strong>。头本身有开销：TCP+IP 头 40 字节，如果数据只有 1 字节，开销率 97.6%。所以小包合并（Nagle 算法）是有意义的。</li><li><strong>ARP 到底属于哪一层有争议</strong>。它工作在链路层和网络层之间，通常归为链路层，但它处理的是 IP 地址。</li><li><strong>&quot;OSI 七层&quot;不要和&quot;TCP/IP 四层&quot;混着说</strong>。面试时先答四层（实际），再提七层（模型）。</li><li><strong>IP 头不变，但 IP 包可能被分片</strong>。分片后每个分片有自己的 IP 头（部分字段复制），重组在目的主机完成。</li></ul><h2 id="✅-验收清单" tabindex="-1">✅ 验收清单 <a class="header-anchor" href="#✅-验收清单" aria-label="Permalink to &quot;✅ 验收清单&quot;">​</a></h2><ul><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="0"> 能画出封装/解封装图，标出每层加的头和头里的关键字段</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="1"> 能说出路由器转发时&quot;什么变、什么不变&quot;（MAC 变、IP 不变、TTL 减 1）</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="2"> 能解释为什么路由器只拆到 IP 层（端到端原则）</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="3"> 能用四元组解释&quot;一个 80 端口为什么能扛上万连接&quot;</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="4"> 能算出 MSS = MTU - 40，并说出为什么要切段</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="5"> 能解释 TTL 的两个作用（防环 + traceroute 原理）</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="6"> 合上书，用自己的话讲 3 分钟，中途不卡壳</li></ul>`,70)])])}const h=a(e,[["render",o]]);export{d as __pageData,h as default};
